package com.cartalaap.marketplace;
import java.util.List;import java.util.Optional;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.domain.Specification;import org.springframework.data.jpa.repository.EntityGraph;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.JpaSpecificationExecutor;
public interface MarketplaceListingRepository extends JpaRepository<MarketplaceListing,Long>,JpaSpecificationExecutor<MarketplaceListing>{@Override@EntityGraph(attributePaths={"seller","images"})Page<MarketplaceListing> findAll(Specification<MarketplaceListing> spec,Pageable pageable);@EntityGraph(attributePaths={"seller","images"})Optional<MarketplaceListing> findDetailedById(Long id);@EntityGraph(attributePaths={"seller","images"})List<MarketplaceListing> findBySeller_IdOrderByCreatedAtDesc(Long sellerId);}
